const input = $json.body ?? $json;

const name = typeof input.name === 'string' ? input.name.trim() : '';
const email = typeof input.email === 'string' ? input.email.trim() : '';
const message = typeof input.message === 'string' ? input.message.trim() : '';

if (!name || !email.includes('@') || !message) {
  throw new Error('name, valid email, and message are required');
}

return [{
  json: {
    source: 'public-showcase-demo',
    lead: { name, email, message },
    classification_request: {
      allowed_output_fields: ['category', 'intent', 'summary'],
      note: 'In production this step is sent to the AI classification layer.'
    }
  }
}];

// Demo-only deterministic classification.
// The production project uses an AI classification workflow, which is private.
const lead = $json.lead;
const normalized = lead.message.toLowerCase();

const category = normalized.includes('urgent') ? 'Hot' : 'Warm';
const intent = normalized.includes('demo') ? 'Product demo' : 'General inquiry';

return [{
  json: {
    ...$json,
    ai_result: {
      category,
      intent,
      summary: `Lead from ${lead.name} passed the sanitized intake example.`
    }
  }
}];

// Merge authoritative source fields with only the classification fields
// this workflow is allowed to produce.
return [{
  json: {
    lead: $json.lead,
    classification: {
      category: $json.ai_result.category,
      intent: $json.ai_result.intent,
      summary: $json.ai_result.summary
    },
    persisted: false,
    note: 'No database write is included in this public example.'
  }
}];
